-- Fail closed on unreviewed default/direct grants; inherited role membership is a provisioning gate.
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_class c,LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
 WHERE c.oid IN ('"account_merge_events"'::regclass,'"agent_heartbeats"'::regclass,'"agent_runs"'::regclass,'"aiprompts"'::regclass,'"artist_activity_events"'::regclass,'"artist_bio_corrections"'::regclass,'"mn_private"."artist_bio_provenance"'::regclass,'"mn_private"."artist_bio_version_provenance"'::regclass,'"artist_bio_versions"'::regclass,'"artist_claims"'::regclass,'"artist_directory_preparations"'::regclass,'"artist_doc_corrections"'::regclass,'"artist_docs"'::regclass,'"artist_id_mappings"'::regclass,'"artist_interview_answer_versions"'::regclass,'"artist_interview_answers"'::regclass,'"artist_interview_boundaries"'::regclass,'"artist_interview_question_evidence"'::regclass,'"artist_interview_sessions"'::regclass,'"artist_latest_provider_snapshots"'::regclass,'"artist_mapping_exclusions"'::regclass,'"artist_onboarding_interview_plans"'::regclass,'"artist_onboarding_steps"'::regclass,'"artist_question_answers"'::regclass,'"artist_question_requests"'::regclass,'"artist_research_candidates"'::regclass,'"artist_research_evidence"'::regclass,'"artist_research_jobs"'::regclass,'"artist_self_edits"'::regclass,'"artist_social_credits"'::regclass,'"artist_social_post_versions"'::regclass,'"artist_social_posts"'::regclass,'"artist_social_profiles"'::regclass,'"artist_social_refreshes"'::regclass,'"artist_source_assessments"'::regclass,'"artist_vault_source_versions"'::regclass,'"artist_vault_sources"'::regclass,'"artists"'::regclass,'"bot_prompts"'::regclass,'"musicnerd_private"."catalog_link_disconnects"'::regclass,'"featured"'::regclass,'"history"'::regclass,'"mn_private"."legacy_bio_publications"'::regclass,'"mcp_api_keys"'::regclass,'"mcp_audit_log"'::regclass,'"provider_request_cooldowns"'::regclass,'"mn_private"."public_url_receipts"'::regclass,'"question_planning_admissions"'::regclass,'"ugcresearch"'::regclass,'"urlmap"'::regclass,'"user_tracks"'::regclass,'"users"'::regclass,'"wrap_guilds"'::regclass) AND a.grantee NOT IN (c.relowner,(SELECT oid FROM pg_roles WHERE rolname='mnweb')))
 OR EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace,
 LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
 WHERE n.nspname||'.'||p.proname IN ('public.transfer_account_activity','public.knowledge_vault_source_snapshot','public.knowledge_social_post_snapshot','public.knowledge_source_fingerprint','public.retain_vault_source_version','public.retain_social_post_version','musicnerd_private.disconnect_catalog_link','musicnerd_private.catalog_link_was_disconnected','musicnerd_private.queue_catalog_counterpart','musicnerd_private.queue_catalog_counterpart_after_write','musicnerd_private.validate_catalog_identity_write','musicnerd_private.lock_catalog_exclusion_artist','mn_private.consume_legacy_bio_publication','mn_private.lock_lore_activity_events') AND (a.grantee NOT IN (p.proowner,(SELECT oid FROM pg_roles WHERE rolname='mnweb')) OR (p.prosecdef AND a.grantee<>p.proowner AND p.oid<>'mn_private.lock_lore_activity_events(uuid)'::regprocedure)))
 THEN RAISE EXCEPTION 'Unexpected prototype object grants'; END IF;
END $$;
